  echo "guard: changes outside this service's write scope (.guard/paths.allow):"
  printf '  %s\n' "${bad[@]}"
  exit 1
fi
echo "guard: ok ($(printf '%s\n' "$changed" | grep -c . || true) changed files, all within write scope)"
